const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  // Southern Iran region (approximate polygon)
  var southernIran = ee.Geometry.Polygon([
    [51.0, 25.0],
    [61.0, 25.0], 
    [61.0, 30.0],
    [51.0, 30.0],
    [51.0, 25.0]
  ]);

  // 2. Data Acquisition - JRC Global Surface Water Monthly History
  var dec2021 = ee.Image('JRC/GSW1_3/MonthlyHistory/2021_12')
    .select('water');
  var jan2022 = ee.Image('JRC/GSW1_3/MonthlyHistory/2022_01')
    .select('water');

  // Check if images exist
  try {
    var decInfo = dec2021.getInfo();
    var janInfo = jan2022.getInfo();
  } catch (e) {
    print("Error accessing JRC data");
    print("<answer>C1</answer>");
    return;
  }

  // 3. Processing - Extract water pixels (value = 2 for water)
  var decWater = dec2021.eq(2).selfMask();
  var janWater = jan2022.eq(2).selfMask();

  // 4. Calculate water extent
  var decStats = decWater.reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: southernIran,
    scale: 1000,
    maxPixels: 1e9
  });

  var janStats = janWater.reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: southernIran,
    scale: 1000,
    maxPixels: 1e9
  });

  var decWaterPixels = decStats.get('water').getInfo();
  var janWaterPixels = janStats.get('water').getInfo();

  // 5. Validation & Final Answer
  print("December 2021 water pixels: " + decWaterPixels);
  print("January 2022 water pixels: " + janWaterPixels);

  if (decWaterPixels === null || janWaterPixels === null) {
    print("<answer>C3</answer>");
  } else if (decWaterPixels === 0 || janWaterPixels === 0) {
    print("<answer>C2</answer>");
  } else if (janWaterPixels > decWaterPixels) {
    print("Water extent increased");
    print("<answer>A</answer>");
  } else {
    print("Water extent did not increase");
    print("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
